`,xr=(n,i)=>n.layout.elements.year.height*i.yearIndex+n.layout.topMargin,ji=(n,i)=>(n.layout.elements.character.width+n.layout.elements.character.spacer)*i.index+n.layout.elements.character.leftPageMargin,Vi=(n,i)=>tc(n)-n.layout.elements.year.height*i.yearIndex,dc=X(({character:n,...i})=>w.jsx("div",{...i,"data-testid":"character"}))`
